//! Herdr collector — polls herdr's JSON-RPC API over a Unix socket.
//!
//! Connects to herdr via `$HERDR_SOCKET_PATH`, calls `pane.list`,
//! and emits `HerdrPaneSnapshot` structs for the reducer.

use interprocess::local_socket::prelude::*;
use interprocess::local_socket::GenericFilePath;
use mc_schema::pane_view::AgentStatus;
use mc_schema::raw_signals::HerdrPaneSnapshot;
use serde::Deserialize;
use serde_json::Value;
use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;

/// Error from the herdr collector.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("socket path not set (set $HERDR_SOCKET_PATH or config)")]
    NoSocketPath,
    #[error("herdr I/O: {0}")]
    Io(#[from] std::io::Error),
    #[error("herdr JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("herdr returned error: {0}")]
    ApiError(String),
    #[error("unexpected herdr response shape")]
    UnexpectedResponse,
}

/// Raw response from herdr's `pane.list` method.
/// herdr wraps the result in `{"id":"...","result":{"panes":[...]}}`.
#[derive(Debug, Deserialize)]
struct WorkspaceListResponse {
    result: WorkspaceListResult,
}

#[derive(Debug, Deserialize)]
struct WorkspaceListResult {
    workspaces: Vec<WorkspaceInfo>,
}

#[derive(Debug, Deserialize)]
struct WorkspaceInfo {
    workspace_id: String,
    #[serde(default)]
    label: Option<String>,
}

#[derive(Debug, Deserialize)]
struct TabListResponse {
    result: TabListResult,
}

#[derive(Debug, Deserialize)]
struct TabListResult {
    tabs: Vec<TabInfo>,
}

#[derive(Debug, Deserialize)]
struct TabInfo {
    tab_id: String,
    #[serde(default)]
    label: Option<String>,
}

#[derive(Debug, Deserialize)]
struct HerdrResponse {
    result: PaneListResult,
}

#[derive(Debug, Deserialize)]
struct PaneListResult {
    panes: Vec<HerdrPaneInfo>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "snake_case")]
struct HerdrPaneInfo {
    pane_id: String,
    workspace_id: String,
    tab_id: String,
    #[serde(default)]
    agent: Option<String>,
    #[serde(default)]
    agent_status: HerdrAgentStatus,
    #[serde(default)]
    focused: bool,
    #[serde(default)]
    cwd: Option<String>,
    #[serde(default)]
    agent_session: Option<HerdrAgentSession>,
    #[serde(default)]
    custom_status: Option<String>,
}

#[derive(Debug, Deserialize)]
struct HerdrAgentSession {
    value: String,
}

#[derive(Debug, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
enum HerdrAgentStatus {
    Idle,
    Working,
    Blocked,
    Done,
    #[default]
    Unknown,
}

impl From<HerdrAgentStatus> for AgentStatus {
    fn from(s: HerdrAgentStatus) -> Self {
        match s {
            HerdrAgentStatus::Idle => AgentStatus::Idle,
            HerdrAgentStatus::Working => AgentStatus::Working,
            HerdrAgentStatus::Blocked => AgentStatus::Blocked,
            HerdrAgentStatus::Done => AgentStatus::Done,
            HerdrAgentStatus::Unknown => AgentStatus::Unknown,
        }
    }
}

/// Resolve the herdr socket path from environment or config.
pub fn herdr_socket_path() -> Result<PathBuf, Error> {
    // 1. Check $HERDR_SOCKET_PATH (set by herdr in every pane)
    if let Ok(path) = std::env::var("HERDR_SOCKET_PATH") {
        return Ok(PathBuf::from(path));
    }
    // 2. Check config override
    let config = crate::config::Config::load();
    if let Some(path) = config.herdr_socket {
        return Ok(path);
    }
    // 3. Fallback default
    Ok(dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("herdr")
        .join("herdr.sock"))
}

/// Fetch all panes from herdr, enriched with workspace/tab labels.
pub fn fetch_panes(socket_path: &Path, timeout: Duration) -> Result<Vec<HerdrPaneSnapshot>, Error> {
    let mut stream = connect(&socket_path, timeout)?;

    // Fetch workspace labels
    send_request(&mut stream, "mc-ws", "workspace.list")?;
    let ws_response: WorkspaceListResponse = read_response(&mut stream)?;
    let ws_labels: HashMap<String, String> = ws_response
        .result
        .workspaces
        .into_iter()
        .filter_map(|ws| ws.label.map(|l| (ws.workspace_id, l)))
        .collect();

    // Fetch tab labels
    let mut stream = connect(&socket_path, timeout)?;
    send_request(&mut stream, "mc-tab", "tab.list")?;
    let tab_response: TabListResponse = read_response(&mut stream)?;
    let tab_labels: HashMap<String, String> = tab_response
        .result
        .tabs
        .into_iter()
        .filter_map(|t| t.label.map(|l| (t.tab_id, l)))
        .collect();

    // Fetch panes
    let mut stream = connect(&socket_path, timeout)?;
    send_request(&mut stream, "mc-status", "pane.list")?;
    let response: HerdrResponse = read_response(&mut stream)?;

    let now = chrono::Utc::now();
    let panes = response
        .result
        .panes
        .into_iter()
        .map(|p| {
            let cwd = p.cwd.unwrap_or_else(|| ".".into());
            let agent_session_path = p.agent_session.map(|s| PathBuf::from(s.value));

            // Fallback: if pi is running but herdr lost the session path,
            // scan the session directory by cwd and pick the newest file.
            let agent_session_path = if agent_session_path.is_none()
                && p.agent.as_deref() == Some("pi")
                && cwd != "."
            {
                find_orphaned_session_path(&cwd)
                    .or_else(|| find_orphaned_session_path_by_header(&cwd))
            } else {
                agent_session_path
            };

            HerdrPaneSnapshot {
                workspace_id: p.workspace_id.clone(),
                workspace_label: ws_labels.get(&p.workspace_id).cloned(),
                tab_id: p.tab_id.clone(),
                tab_label: tab_labels.get(&p.tab_id).cloned(),
                pane_id: p.pane_id,
                agent: p.agent,
                agent_status: p.agent_status.into(),
                focused: p.focused,
                cwd: cwd.into(),
                agent_session_path,
                custom_status: p.custom_status,
                captured_at: now,
            }
        })
        .collect();

    Ok(panes)
}

/// Connect to herdr's Unix socket with a timeout.
fn connect(path: &Path, timeout: Duration) -> std::io::Result<interprocess::local_socket::Stream> {
    let name = path.to_fs_name::<GenericFilePath>()
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidInput, e))?;
    let stream = interprocess::local_socket::Stream::connect(name)?;
    stream.set_send_timeout(Some(timeout))?;
    stream.set_recv_timeout(Some(timeout))?;
    Ok(stream)
}

/// Send a JSON-RPC request to herdr (newline-delimited JSON).
fn send_request(stream: &mut interprocess::local_socket::Stream, id: &str, method: &str) -> Result<(), Error> {
    let request = serde_json::json!({
        "id": id,
        "method": method,
        "params": {},
    });
    stream.write_all(serde_json::to_string(&request)?.as_bytes())?;
    stream.write_all(b"\n")?;
    stream.flush()?;
    Ok(())
}

/// Read a single newline-delimited JSON response from herdr.
fn read_response<T: serde::de::DeserializeOwned>(
    stream: &mut interprocess::local_socket::Stream,
) -> Result<T, Error> {
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    let read = reader.read_line(&mut line)?;
    if read == 0 || line.trim().is_empty() {
        return Err(Error::UnexpectedResponse);
    }
    serde_json::from_str(&line).map_err(Error::Json)
}

// ── Pi session directory helpers ──────────────────────────────────────────

/// Pi's session directory (default: ~/.pi/agent/sessions/).
fn pi_sessions_dir() -> PathBuf {
    dirs::home_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join(".pi")
        .join("agent")
        .join("sessions")
}

/// Convert a cwd path to pi's session directory slug.
/// E.g. `/home/anupam/Desktop/workspace` → `--home-anupam-Desktop-workspace--`
fn cwd_to_slug(cwd: &str) -> String {
    let slug = cwd.trim_start_matches('/').replace('/', "-");
    if slug.is_empty() {
        return "--root--".to_string();
    }
    format!("--{}--", slug)
}

/// Find the newest `.jsonl` session file in the directory for the given cwd.
/// Matches by directory slug derived from the cwd path, then verifies the
/// session header `cwd` field matches.
pub fn find_orphaned_session_path(cwd: &str) -> Option<PathBuf> {
    let session_dir = pi_sessions_dir().join(cwd_to_slug(cwd));
    let candidate = find_newest_jsonl(&session_dir)?;

    // Verify the session header cwd matches
    let content = fs::read_to_string(&candidate).ok()?;
    let first_line = content.lines().next()?;
    let val: Value = serde_json::from_str(first_line).ok()?;
    if val.get("cwd").and_then(|v| v.as_str()) == Some(cwd) {
        Some(candidate)
    } else {
        None
    }
}

/// Fallback: scan ALL session directories for a session whose header `cwd`
/// matches the given cwd. This catches cases where the slug algorithm doesn't
/// exactly match pi's internal slug generation.
pub fn find_orphaned_session_path_by_header(cwd: &str) -> Option<PathBuf> {
    let sessions_dir = pi_sessions_dir();
    let dir = match fs::read_dir(&sessions_dir) {
        Ok(d) => d,
        Err(_) => return None,
    };

    let mut candidates: Vec<PathBuf> = Vec::new();
    for entry in dir.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        if let Some(newest) = find_newest_jsonl(&path) {
            // Read the first line to check the cwd header
            if let Ok(content) = fs::read_to_string(&newest) {
                if let Some(first_line) = content.lines().next() {
                    if let Ok(val) = serde_json::from_str::<Value>(first_line) {
                        if val.get("cwd").and_then(|v| v.as_str()) == Some(cwd) {
                            candidates.push(newest);
                        }
                    }
                }
            }
        }
    }

    // Pick the newest by modification time
    candidates.sort_by(|a, b| {
        let mta = fs::metadata(a).and_then(|m| m.modified()).ok();
        let mtb = fs::metadata(b).and_then(|m| m.modified()).ok();
        mta.cmp(&mtb).reverse()
    });

    candidates.into_iter().next()
}

/// Find the newest `.jsonl` file in a directory.
fn find_newest_jsonl(dir: &Path) -> Option<PathBuf> {
    let read_dir = match fs::read_dir(dir) {
        Ok(d) => d,
        Err(_) => return None,
    };

    let mut newest: Option<PathBuf> = None;
    let mut newest_mtime: Option<std::time::SystemTime> = None;

    for entry in read_dir.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
            continue;
        }
        if let Ok(meta) = fs::metadata(&path) {
            if meta.len() == 0 {
                continue; // skip files being written to
            }
            if let Ok(mtime) = meta.modified() {
                if newest_mtime.map_or(true, |old| mtime > old) {
                    newest = Some(path);
                    newest_mtime = Some(mtime);
                }
            }
        }
    }

    newest
}

//! `mc diagnose` — inspect session-to-pane mapping and orphaned sessions.
//!
//! Connects to the daemon, fetches the pane list, scans the pi session
//! directory, and shows a report of what's mapped vs orphaned.

use interprocess::local_socket::prelude::*;
use interprocess::local_socket::GenericFilePath;
use mc_schema::events::SnapshotResponse;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;

/// Default socket path (same as daemon.rs)
fn daemon_socket_path() -> PathBuf {
    dirs::runtime_dir()
        .or_else(|| dirs::cache_dir())
        .unwrap_or_else(|| PathBuf::from("/tmp"))
        .join("mc.sock")
}

/// Pi session directory
fn pi_session_dir() -> PathBuf {
    dirs::home_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join(".pi")
        .join("agent")
        .join("sessions")
}

pub fn run() {
    let socket_path = daemon_socket_path();
    let sessions_dir = pi_session_dir();

    if !socket_path.exists() {
        eprintln!("mc: daemon socket not found at {}", socket_path.display());
        eprintln!("mc: is `mc serve` running?");
        std::process::exit(1);
    }

    // Fetch snapshot from daemon
    let snapshot = match daemon_call(&socket_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("mc: daemon error: {e}");
            std::process::exit(1);
        }
    };

    // Collect all session files from session dirs
    let mut all_sessions: Vec<SessionEntry> = Vec::new();
    scan_session_dirs(&sessions_dir, &mut all_sessions);

    // Collect mapped session paths from panes
    let mut mapped_paths: std::collections::HashSet<PathBuf> = std::collections::HashSet::new();
    let mut panes_with_sessions: Vec<&PaneInfo> = Vec::new();
    let mut panes_without_sessions: Vec<&PaneInfo> = Vec::new();

    let panes: Vec<PaneInfo> = snapshot
        .panes
        .iter()
        .map(|p| PaneInfo {
            pane_id: p.pane_id.clone(),
            workspace_name: p.workspace_name.clone().unwrap_or_default(),
            tab_name: p.tab_name.clone().unwrap_or_default(),
            agent: p.agent.clone().unwrap_or_default(),
            agent_status: format!("{:?}", p.agent_status).to_lowercase(),
            session_path: p.session_path.clone(),
            total_cost: p.vitals.total_cost_usd,
            total_tool_calls: p.vitals.total_tool_calls,
            arc_turns: p.arc.len(),
        })
        .collect();

    for pane in &panes {
        if let Some(ref path) = pane.session_path {
            mapped_paths.insert(path.clone());
            panes_with_sessions.push(pane);
        } else {
            panes_without_sessions.push(pane);
        }
    }

    // Separate orphaned and mapped sessions
    let mut orphaned: Vec<&SessionEntry> = Vec::new();
    let mut mapped_sessions: Vec<&SessionEntry> = Vec::new();

    for session in &all_sessions {
        if mapped_paths.contains(&session.path) {
            mapped_sessions.push(session);
        } else {
            orphaned.push(session);
        }
    }

    // Sort orphaned by mtime descending
    orphaned.sort_by(|a, b| b.mtime.cmp(&a.mtime));

    // ── Report ────────────────────────────────────────────────

    println!("═══ mc diagnose — session mapping report ═══");
    println!();

    // Summary
    println!("Summary:");
    println!("  Panes:             {:3}", panes.len());
    println!("  With session:      {:3}", panes_with_sessions.len());
    println!("  Without session:   {:3}", panes_without_sessions.len());
    println!(
        "  Session files:     {:3}",
        all_sessions.len()
    );
    println!("  Mapped to panes:   {:3}", mapped_sessions.len());
    println!("  Orphaned on disk:  {:3}", orphaned.len());
    println!(
        "  Total cost:        ${:.2}",
        panes.iter().map(|p| p.total_cost).sum::<f64>()
    );
    println!();

    // Panes with sessions
    println!("═══ Panes WITH session ──────────────────────────────");
    println!(
        "{:<40} {:<22}  {:>8}  {:>5}  {:>5}",
        "Pane", "Session", "Cost", "Turns", "Tools"
    );
    for p in &panes_with_sessions {
        let label = if !p.workspace_name.is_empty() && !p.tab_name.is_empty() {
            format!("{} / {}", p.workspace_name, p.tab_name)
        } else {
            p.pane_id.clone()
        };
        let session_id = p
            .session_path
            .as_ref()
            .and_then(|sp| sp.file_stem())
            .and_then(|s| s.to_str())
            .map(|s| truncate_mid(s, 22))
            .unwrap_or_default();
        println!(
            "{:<40} {:<22}  ${:>7.2}  {:>5}  {:>5}",
            label, session_id, p.total_cost, p.arc_turns, p.total_tool_calls
        );
    }
    println!();

    // Panes without sessions
    if !panes_without_sessions.is_empty() {
        println!("═══ Panes WITHOUT session ────────────────────────────");
        for p in &panes_without_sessions {
            let label = if !p.workspace_name.is_empty() && !p.tab_name.is_empty() {
                format!("{} / {}", p.workspace_name, p.tab_name)
            } else {
                p.pane_id.clone()
            };
            println!("  {}  (status: {})", label, p.agent_status);
        }
        println!();
    }

    // Orphaned sessions (show recent ones that might match the 4 panes)
    if !orphaned.is_empty() {
        println!("═══ Orphaned session files (top 20 by recency) ────────");
        println!(
            "{:<30} {:>10}  {:>12}  {:<20}",
            "Session ID", "Size", "Last Modified", "CWD"
        );
        for s in orphaned.iter().take(20) {
            println!(
                "{:<30} {:>8}KB  {:>12}  {:<20}",
                truncate(s.session_id(), 28),
                s.size_kb,
                s.mtime_str(),
                truncate(&s.cwd(), 18)
            );
        }
        if orphaned.len() > 20 {
            println!("  ... and {} more", orphaned.len() - 20);
        }
        println!();
    }

    // Recommendations
    println!("═══ Recommendations ──────────────────────────────────");
    if panes_without_sessions.len() > 0 {
        println!(
            "  • {} panes have no session associated.",
            panes_without_sessions.len()
        );
        println!("    The collector needs a fallback scan of the orphaned session files");
        println!("    matching by cwd + recency to recover their data.");
    }
    if orphaned.len() > 0 {
        println!(
            "  • {} orphaned session files on disk are not linked to any pane.",
            orphaned.len()
        );
        println!("    Add orphaned-session fallback in mc-core/src/collector/herdr.rs:");
        println!("    when agent_session_path is None, scan session files matching cwd.");
    }
    println!(
        "  • Total tracked cost: ${:.2} across {} panes.",
        panes.iter().map(|p| p.total_cost).sum::<f64>(),
        panes.len()
    );
    println!("  • Total orphaned sessions could add more cost data if recovered.");
    println!();
}

// ── Helpers ────────────────────────────────────────────────────────

struct PaneInfo {
    pane_id: String,
    workspace_name: String,
    tab_name: String,
    agent: String,
    agent_status: String,
    session_path: Option<PathBuf>,
    total_cost: f64,
    total_tool_calls: u32,
    arc_turns: usize,
}

struct SessionEntry {
    path: PathBuf,
    size_kb: u64,
    mtime: i64,
}

impl SessionEntry {
    fn session_id(&self) -> &str {
        self.path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("?")
    }

    fn cwd(&self) -> String {
        // Read first line from session file to get cwd
        if let Ok(content) = std::fs::read_to_string(&self.path) {
            if let Some(line) = content.lines().next() {
                if let Ok(header) = serde_json::from_str::<serde_json::Value>(line) {
                    if let Some(cwd) = header.get("cwd").and_then(|c| c.as_str()) {
                        return cwd
                            .rsplit('/')
                            .next()
                            .unwrap_or(cwd)
                            .to_string();
                    }
                }
            }
        }
        String::new()
    }

    fn mtime_str(&self) -> String {
        let dt = chrono::DateTime::from_timestamp(self.mtime, 0).unwrap_or_default();
        dt.format("%b %d %H:%M").to_string()
    }
}

fn scan_session_dirs(dir: &Path, out: &mut Vec<SessionEntry>) {
    let dir_entries = match std::fs::read_dir(dir) {
        Ok(d) => d,
        Err(_) => return,
    };

    for entry in dir_entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            // Recurse into per-cwd session subdirectories
            scan_session_dirs(&path, out);
            continue;
        }
        if path.extension().and_then(|s| s.to_str()) != Some("jsonl") {
            continue;
        }
        let meta = match entry.metadata() {
            Ok(m) => m,
            _ => continue,
        };
        out.push(SessionEntry {
            size_kb: (meta.len() + 512) / 1024,
            mtime: meta
                .modified()
                .ok()
                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|d| d.as_secs() as i64)
                .unwrap_or(0),
            path,
        });
    }
}

fn daemon_call(socket_path: &Path) -> Result<SnapshotResponse, String> {
    let mut stream = interprocess::local_socket::Stream::connect(
        socket_path
            .to_fs_name::<GenericFilePath>()
            .map_err(|e| format!("socket error: {e}"))?,
    )
    .map_err(|e| format!("connect error: {e}"))?;

    stream
        .set_send_timeout(Some(Duration::from_secs(3)))
        .unwrap_or(());
    stream
        .set_recv_timeout(Some(Duration::from_secs(3)))
        .unwrap_or(());

    let request = serde_json::json!({
        "id": "diagnose",
        "method": "mc.snapshot",
        "params": null,
    });

    stream
        .write_all(serde_json::to_string(&request).unwrap().as_bytes())
        .map_err(|e| format!("write error: {e}"))?;
    stream
        .write_all(b"\n")
        .map_err(|e| format!("write error: {e}"))?;
    stream
        .flush()
        .map_err(|e| format!("flush error: {e}"))?;

    let mut reader = BufReader::new(&stream);
    let mut line = String::new();
    reader
        .read_line(&mut line)
        .map_err(|e| format!("read error: {e}"))?;

    let resp: serde_json::Value =
        serde_json::from_str(&line).map_err(|e| format!("parse error: {e}"))?;

    let result = resp
        .get("result")
        .ok_or_else(|| "no result in response".to_string())?;

    serde_json::from_value(result.clone()).map_err(|e| format!("snapshot parse: {e}"))
}

fn truncate(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        format!("{}…", &s[..max.saturating_sub(1)])
    }
}

fn truncate_mid(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else if max < 5 {
        s[..max].to_string()
    } else {
        let left = (max - 3) / 2;
        let right = max - 3 - left;
        format!("{}…{}", &s[..left], &s[s.len() - right..])
    }
}

> pi can create extensions. Ask it to build one for your use case.

# Extensions

Extensions are TypeScript modules that extend pi's behavior. They can subscribe to lifecycle events, register custom tools callable by the LLM, add commands, and more.

> **Placement for /reload:** Put extensions in `~/.pi/agent/extensions/` (global) or `.pi/extensions/` (project-local) for auto-discovery. Use `pi -e ./path.ts` only for quick tests. Extensions in auto-discovered locations can be hot-reloaded with `/reload`.

**Key capabilities:**
- **Custom tools** - Register tools the LLM can call via `pi.registerTool()`
- **Event interception** - Block or modify tool calls, inject context, customize compaction
- **User interaction** - Prompt users via `ctx.ui` (select, confirm, input, notify)
- **Custom UI components** - Full TUI components with keyboard input via `ctx.ui.custom()` for complex interactions
- **Custom commands** - Register commands like `/mycommand` via `pi.registerCommand()`
- **Session persistence** - Store state that survives restarts via `pi.appendEntry()`
- **Custom rendering** - Control how tool calls/results and messages appear in TUI

**Example use cases:**
- Permission gates (confirm before `rm -rf`, `sudo`, etc.)
- Git checkpointing (stash at each turn, restore on branch)
- Path protection (block writes to `.env`, `node_modules/`)
- Custom compaction (summarize conversation your way)
- Conversation summaries (see `summarize.ts` example)
- Interactive tools (questions, wizards, custom dialogs)
- Stateful tools (todo lists, connection pools)
- External integrations (file watchers, webhooks, CI triggers)
- Games while you wait (see `snake.ts` example)

See [examples/extensions/](../examples/extensions/) for working implementations.

